std::vector<Adhesion::Node> nodes;
for (auto it = rt.finite_cells_begin(); it != rt.finite_cells_end(); ++it) {
    Adhesion::Node node;
    node.position = it->vertex(0)->point().coordinates();
    node.velocity = velocity(it);
    node.mass = it->vertex(0)->weight();
    int edge_count_value = edge_count(it, threshold);
    node.node_type = type_from_edge_count(edge_count_value);
    nodes.push_back(node);
}
return nodes;

